import sys

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            amount = float(line)
        except ValueError:
            continue
        rounded = round(amount * 20) / 20
        if rounded == 0:
            print("0.00")
        else:
            print("{:.2f}".format(rounded))


if __name__ == "__main__":
    main()
